#!/usr/bin/env python3
import json
import os
from pathlib import Path
from datetime import datetime
import sys

sessions_dir = "/Users/sa/.claude/projects/-Users-sa-rh-1"
sessions = []

for jsonl_file in sorted(Path(sessions_dir).glob("*.jsonl")):
    session_id = jsonl_file.stem
    file_size_kb = jsonl_file.stat().st_size / 1024
    mod_time = datetime.fromtimestamp(jsonl_file.stat().st_mtime)

    first_messages = []
    last_messages = []
    key_topics = set()
    files_touched = set()
    death_cause = "unknown"

    try:
        # Read first 100 lines
        with open(jsonl_file, 'r') as f:
            for i, line in enumerate(f):
                if i < 100:
                    try:
                        entry = json.loads(line)
                        first_messages.append(entry)
                    except:
                        pass
                else:
                    break

        # Read last 50 lines by seeking to end
        with open(jsonl_file, 'r') as f:
            lines = f.readlines()
            for line in lines[-50:]:
                try:
                    entry = json.loads(line)
                    last_messages.append(entry)
                except:
                    pass

        # Extract info from messages
        for entry in first_messages + last_messages:
            if isinstance(entry, dict):
                # Extract topics from content
                if "content" in entry:
                    content = str(entry.get("content", "")).lower()
                    if "file" in content or "write" in content:
                        key_topics.add("file operations")
                    if "commit" in content:
                        key_topics.add("git/commit")
                    if "test" in content:
                        key_topics.add("testing")
                    if "bridge" in content or "provider" in content or "model" in content:
                        key_topics.add("LLM bridge")
                    if "agent" in content or "orchestrat" in content:
                        key_topics.add("agent orchestration")
                    if "chronos" in content:
                        key_topics.add("Chronos protocol")
                    if "memory" in content:
                        key_topics.add("memory system")
                    if "state" in content:
                        key_topics.add("state management")

                # Look for file references
                if "tool" in entry:
                    tool = entry.get("tool", {})
                    if tool.get("name") in ["Write", "Edit", "NotebookEdit"]:
                        if "file_path" in tool.get("parameters", {}):
                            files_touched.add(tool["parameters"]["file_path"])

        # Check how it ended
        if last_messages:
            last = last_messages[-1]
            if isinstance(last, dict):
                if "error" in str(last).lower():
                    death_cause = "error"
                elif "context" in str(last).lower() and "overflow" in str(last).lower():
                    death_cause = "context overflow"
                else:
                    death_cause = "normal"

        # Extract first user message summary
        first_summary = ""
        for entry in first_messages:
            if isinstance(entry, dict) and entry.get("role") == "user":
                content = entry.get("content", "")
                if isinstance(content, str):
                    first_summary = content[:120].replace("\n", " ")
                    break

        # Extract last message summary
        last_summary = ""
        for entry in reversed(last_messages):
            if isinstance(entry, dict):
                content = entry.get("content", "")
                if isinstance(content, str):
                    last_summary = content[:120].replace("\n", " ")
                    break

        sessions.append({
            "id": session_id,
            "date": mod_time,
            "size_kb": file_size_kb,
            "first_summary": first_summary,
            "last_summary": last_summary,
            "topics": sorted(list(key_topics)),
            "files": sorted(list(files_touched)),
            "death_cause": death_cause
        })
    except Exception as e:
        print(f"Error processing {session_id}: {e}", file=sys.stderr)
        continue

# Sort by modification date
sessions.sort(key=lambda x: x["date"])

# Print as structured data for further processing
for s in sessions:
    print(json.dumps(s, default=str))
EOF
