  0→# Automating React/Radix UI Web Applications
  1→
  2→## The Core Problem
  3→Modern React apps don't respond to simple `.click()`. They use synthetic event systems.
  4→
  5→## Solution: Full Pointer Event Chain
  6→```javascript
  7→// This FAILS on React/Radix buttons:
  8→button.click();
  9→
 10→// This WORKS:
 11→["pointerdown", "mousedown", "pointerup", "mouseup", "click"].forEach(evt => {
 12→  button.dispatchEvent(new MouseEvent(evt, {
 13→    bubbles: true,
 14→    cancelable: true,
 15→    view: window
 16→  }));
 17→});
 18→```
 19→
 20→## Menu/Dialog Automation Pattern
 21→
 22→```javascript
 23→async function automateMenuAction(triggerSelector, menuItemText, confirmBtnText) {
 24→  // 1. Click trigger button (full event chain)
 25→  var btn = document.querySelector(triggerSelector);
 26→  btn.scrollIntoView({block: "center"});
 27→  ["pointerdown","mousedown","pointerup","mouseup","click"].forEach(evt => {
 28→    btn.dispatchEvent(new MouseEvent(evt, {bubbles:true, cancelable:true, view:window}));
 29→  });
 30→
 31→  // 2. Wait for dropdown
 32→  await new Promise(r => setTimeout(r, 800));
 33→
 34→  // 3. Find and click menu item
 35→  var items = document.querySelectorAll("[role=menuitem]");
 36→  var target = Array.from(items).find(i => i.innerText.trim() === menuItemText);
 37→  target.click();
 38→
 39→  // 4. Wait for confirmation dialog
 40→  await new Promise(r => setTimeout(r, 800));
 41→
 42→  // 5. Find and click confirm button
 43→  var dialog = document.querySelector("[role=dialog]");
 44→  var confirmBtn = Array.from(dialog.querySelectorAll("button"))
 45→    .find(b => b.innerText.trim() === confirmBtnText);
 46→  confirmBtn.click();
 47→
 48→  // 6. Wait for API call to complete
 49→  await new Promise(r => setTimeout(r, 1500));
 50→}
 51→```
 52→
 53→## Batch Automation Loop
 54→
 55→```javascript
 56→async function removeAll() {
 57→  var removed = 0;
 58→  for (var attempt = 0; attempt < 50; attempt++) {
 59→    // Find next target
 60→    var target = document.querySelector("button.my-target");
 61→    if (!target) break;
 62→
 63→    // Execute action sequence
 64→    await automateMenuAction(target, "Remove", "Confirm");
 65→    removed++;
 66→  }
 67→  return "removed " + removed;
 68→}
 69→```
 70→
 71→## DOM Identification Strategies
 72→
 73→### By known text anchor
 74→```javascript
 75→var configBtns = Array.from(document.querySelectorAll("button"))
 76→  .filter(b => b.innerText.trim() === "Configure");
 77→```
 78→
 79→### By aria attributes
 80→```javascript
 81→document.querySelectorAll("[aria-haspopup=menu]")  // dropdown triggers
 82→document.querySelectorAll("[aria-expanded=true]")   // open dropdowns
 83→document.querySelectorAll("[role=dialog]")           // modals
 84→```
 85→
 86→### By Radix UI data attributes
 87→```javascript
 88→document.querySelectorAll("[data-radix-popper-content-wrapper]")  // popovers
 89→document.querySelectorAll("[data-state=open]")                     // open components
 90→```
 91→
 92→### Tag elements for later retrieval
 93→```javascript
 94→configBtns.forEach((btn, i) => btn.setAttribute("data-my-tag", i));
 95→// Later:
 96→document.querySelector('[data-my-tag="0"]');
 97→```
 98→
 99→## Timing Guidelines
100→- After button click: wait 500-800ms for dropdown/dialog
101→- After API-triggering action: wait 1000-1500ms for completion
102→- Before re-querying DOM: wait 300ms for React re-render
103→- Always verify state after waiting (don't assume success)
104→

 0→# Reverse Engineering Any SPA's API
 1→
 2→Works on React, Next.js, Vue, Angular — any SPA that makes API calls.
 3→
 4→## Step 1: Discover API calls already made
 5→```javascript
 6→var entries = performance.getEntriesByType("resource");
 7→var apis = entries
 8→  .filter(e => e.name.includes("api") || e.name.includes("graphql"))
 9→  .map(e => e.name);
10→```
11→
12→## Step 2: Read page-specific JS bundle for endpoint patterns
13→```javascript
14→// Find bundle URL from performance entries
15→var jsChunks = performance.getEntriesByType("resource")
16→  .filter(e => e.name.includes("_next/static/chunks") && e.name.endsWith(".js"))
17→  .map(e => e.name);
18→
19→// Fetch and search a bundle
20→fetch(jsChunks[0]).then(r => r.text()).then(t => {
21→  // Find API path patterns
22→  var paths = t.match(/\/api\/[a-zA-Z_\/{}]+/g);
23→
24→  // Search for action keywords
25→  ["disconnect","delete","remove","create","update"].forEach(kw => {
26→    var idx = t.indexOf(kw);
27→    if (idx > -1) console.log(kw, t.substring(idx-30, idx+80));
28→  });
29→});
30→```
31→
32→## Step 3: Make authenticated calls using browser session
33→```javascript
34→fetch("/api/whatever", {credentials: "include"})
35→  .then(r => r.json())
36→  .then(data => console.log(data));
37→```
38→
39→## Step 4: Monkey-patch fetch to capture future calls
40→```javascript
41→var origFetch = window.fetch;
42→window.__capturedRequests = [];
43→window.fetch = function() {
44→  var url = arguments[0];
45→  var method = (arguments[1] && arguments[1].method) || "GET";
46→  window.__capturedRequests.push({url: url, method: method});
47→  console.log(method, url);
48→  return origFetch.apply(this, arguments);
49→};
50→```
51→
52→## Step 5: Identify DOM patterns for automation
53→```javascript
54→// Find interactive elements by role
55→document.querySelectorAll("[role=menuitem]")     // dropdown items
56→document.querySelectorAll("[role=dialog]")        // modals/confirmations
57→document.querySelectorAll("[aria-haspopup=menu]") // dropdown triggers
58→document.querySelectorAll("[data-state=open]")    // Radix UI open states
59→
60→// Walk DOM from known anchor text to find action buttons
61→var anchor = Array.from(document.querySelectorAll("button"))
62→  .find(b => b.innerText.trim() === "Configure");
63→var row = anchor.parentElement.parentElement;
64→var menuBtn = row.querySelector("button[aria-haspopup=menu]");
65→```
66→
67→## Tips
68→- `performance.getEntriesByType("resource")` shows ALL network requests since page load
69→- JS bundles contain hardcoded API paths — searchable with regex
70→- Browser session cookies authenticate API calls automatically
71→- React Query / SWR cache can be inspected via React DevTools
72→- Radix UI components use `data-state="open"/"closed"` for visibility
